func programControlPath(eventID, sessionID int) templ.SafeURL {
	return templ.SafeURL("/crew/program/" + strconv.Itoa(sessionID) +
		"?event_id=" + strconv.Itoa(eventID))
}

func emergencyConfirmationPath(eventID int) templ.SafeURL {
	return templ.SafeURL("/crew/events/" + strconv.Itoa(eventID) +
		"/emergency-alerts/confirmation")
}

func emergencyClearConfirmationPath(eventID, overrideID int) templ.SafeURL {
	return templ.SafeURL("/crew/events/" + strconv.Itoa(eventID) +
		"/overrides/" + strconv.Itoa(overrideID) + "/clear-confirmation")
}

// overrideTone grades an active Override by how much of the Display it claims.
// Emergency Alert is a persistent fullscreen Replace supplementing the venue
// emergency system, so it is the only kind that earns the danger tone.
func overrideTone(kind store.DisplayOverrideKind) string {
	switch kind {
	case store.DisplayOverrideEmergencyAlert:
		return "danger"
	case store.DisplayOverrideTechnicalDifficulties, store.DisplayOverrideUrgentNotice:
		return "warning"
	default:
		return "neutral"
	}
}

func controlValue(page ControlPage, action, value string) string {
	if page.SubmittedAction != action {
		return ""
	}
	return value
}

func controlNumberValue(page ControlPage, action, raw string, value, fallback int) string {
	if page.SubmittedAction != action {
		return strconv.Itoa(fallback)
	}
	if raw != "" {
		return raw
	}
	return strconv.Itoa(value)
}

func ControlFieldID(action, field string) string {
	if previewAction, activating := strings.CutPrefix(action, "activate-"); activating {
		action = "preview-" + previewAction
	}
	switch field {
	case "confirmed":
		return "override-confirmed"
	case "target_group_key":
		if strings.Contains(action, "stage-message") {
			return "stage-target-group"
		}
		return "technical-target-group"
	case "duration_seconds":
		return action + "-duration"
	default:
		return action + "-" + strings.ReplaceAll(field, "_", "-")
	}
}

func ControlClearFieldID(overrideID int) string {
	return "override-clear-" + strconv.Itoa(overrideID) + "-confirmed"
}

